                except Exception:
                    n = None
            if n is None and isinstance(demands, dict) and demands:
                n = max(demands.keys()) + 1
            ids = list(range(n if n is not None else 1))
        else:
            ids = list(ids)

    if depot not in ids:
        ids = [depot] + [i for i in ids if i != depot]

    customers = [i for i in ids if i != depot]

    def demand_of(i):
        if isinstance(demands, dict):
            return demands.get(i, 0)
        if isinstance(demands, list) and 0 <= i < len(demands):
            return demands[i]
        return 0

    if capacity is None:
        total = 0
        for i in customers:
            total += demand_of(i)
        capacity = max(1, total)

    def coord_of(i):
        if nodes is None:
            return None
        if isinstance(nodes, dict):
            return nodes.get(i, None)
        if isinstance(nodes, list) and 0 <= i < len(nodes):
            return nodes[i]
        return None

    def dist_ij(i, j):
        if dist is not None:
            try:
                return dist[i][j]
            except Exception:
                pass
        ci = coord_of(i)
        cj = coord_of(j)
        if ci is None or cj is None:
            return 0 if i == j else abs(i - j)
        try:
            if len(ci) >= 2 and len(cj) >= 2:
                dx = ci[0] - cj[0]
                dy = ci[1] - cj[1]
                return (dx * dx + dy * dy) ** 0.5
        except Exception:
            pass
        return 0 if i == j else abs(i - j)

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        cost = dist_ij(depot, route[0])
        for idx in range(len(route) - 1):
            cost += dist_ij(route[idx], route[idx + 1])
        cost += dist_ij(route[-1], depot)
        return cost

    unserved = []
    for c in customers:
        unserved.append(c)
    unserved.sort()

    routes = []
    while unserved:
        route = []
        load = 0
        cur = depot
        while True:
            best = None
            best_key = None
            for c in unserved:
                d = demand_of(c)
                if load + d > capacity:
                    continue
                key = (dist_ij(cur, c), -d, c)
                if best is None or key < best_key:
                    best = c
                    best_key = key
            if best is None:
                break
            route.append(best)
            unserved.remove(best)
            load += demand_of(best)
            cur = best
        if not route:
            best = None
            best_key = None
            for c in unserved:
                key = (demand_of(c), dist_ij(depot, c), c)
                if best is None or key < best_key:
                    best = c
                    best_key = key
            route = [best]
            unserved.remove(best)
        routes.append(route)

    def total_cost(rs):
        s = 0
        for r in rs:
            s += route_cost(r)
        return s

    improved = True
    while improved:
        improved = False
        for r_idx in range(len(routes)):
            r = routes[r_idx]
            m = len(r)
            if m < 3:
                continue
            base = route_cost(r)
            best_route = None
            best_delta = 0
            for i in range(m - 1):
                for k in range(i + 1, m):
                    nr = r[:i] + r[i:k + 1][::-1] + r[k + 1:]
                    delta = route_cost(nr) - base
                    if delta < best_delta - 1e-12:
                        best_delta = delta
                        best_route = nr
            if best_route is not None:
                routes[r_idx] = best_route
                improved = True

    changed = True
    while changed:
        changed = False

        for a in range(len(routes)):
            ra = routes[a]
            la = route_load(ra)
            for i in range(len(ra)):
                x = ra[i]
                dx = demand_of(x)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    lb = route_load(rb)
                    if lb + dx > capacity:
                        continue
                    best_rb = None
                    best_cost = None
                    best_pos = None
                    for pos in range(len(rb) + 1):
                        nrb = rb[:pos] + [x] + rb[pos:]
                        nra = ra[:i] + ra[i + 1:]
                        c = route_cost(nra) + route_cost(nrb)
                        if best_rb is None or c < best_cost - 1e-12 or (abs(c - best_cost) <= 1e-12 and pos < best_pos):
                            best_rb = nrb
                            best_cost = c
                            best_pos = pos
                    if best_rb is not None:
                        new_routes = routes[:]
                        new_routes[a] = ra[:i] + ra[i + 1:]
                        new_routes[b] = best_rb
                        if total_cost(new_routes) + 1e-12 < total_cost(routes):
                            routes = new_routes
                            changed = True
                            break
                if changed:
                    break
            if changed:
                break

        if changed:
            continue

        for a in range(len(routes)):
            ra = routes[a]
            la = route_load(ra)
            for b in range(a + 1, len(routes)):
                rb = routes[b]
                lb = route_load(rb)
                best = None
                best_pair = None
                for i in range(len(ra)):
                    x = ra[i]
                    dx = demand_of(x)
                    for j in range(len(rb)):
                        y = rb[j]
                        dy = demand_of(y)
                        if la - dx + dy > capacity:
                            continue
                        if lb - dy + dx > capacity:
                            continue
                        nra = ra[:i] + [y] + ra[i + 1:]
                        nrb = rb[:j] + [x] + rb[j + 1:]
                        c = route_cost(nra) + route_cost(nrb)
                        if best is None or c < best - 1e-12 or (abs(c - best) <= 1e-12 and (i, j, x, y) < best_pair):
                            best = c
                            best_pair = (i, j, x, y)
                if best_pair is not None:
                    i, j, x, y = best_pair
                    nra = ra[:i] + [y] + ra[i + 1:]
                    nrb = rb[:j] + [x] + rb[j + 1:]
                    new_routes = routes[:]
                    new_routes[a] = nra
                    new_routes[b] = nrb
                    if total_cost(new_routes) + 1e-12 < total_cost(routes):
                        routes = new_routes
                        changed = True
                        break
            if changed:
                break

    routes = [r for r in routes if r]
    return routes
